def make_change(amount, notes=(500, 100, 50, 20, 10)):
    result = {}
    for note in notes:
        count = amount // note
        if count:
            result[note] = count
        amount = amount % note
    return result

alt:
def make_change(amount, notes=(500, 100, 50, 20, 10)):
    result = {}
    for note in notes:
        count, amount = divmod(amount, note)
        if count:
            result[note] = count
    return result
